"use client";

/**
 * Ledgerly logo mark: the 3D emerald wallet (Sifat's pick, 2026-11-17),
 * generated by scripts/generate-icons.py into public/logo-3d.png. Used in
 * the app header (top left), the desktop sidebar, and the landing page
 * (header + hero). The earlier flat SVG ledger mark is retired.
 */
export function Logo({ className = "h-9 w-9" }: { className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src="/logo-3d.png"
      alt="Ledgerly logo"
      className={`${className} rounded-[23%]`}
    />
  );
}

/** Logo mark + wordmark, as used in the app and landing headers. */
export function LogoLockup() {
  return (
    <span className="flex items-center gap-2.5">
      <Logo className="h-9 w-9 shrink-0" />
      <span className="text-lg font-bold tracking-tight">Ledgerly</span>
    </span>
  );
}
